// @vegastack use-drag-reorder@0.23.100 sha256-DzDYjTsVZY4Gki+iOtDlwc/5Y9tV1Mf0D/Y4gQh/fFI=

"use client";

import * as React from "react";
import {
  useAnnouncer,
  type AnnouncerProps,
} from "@/components/ui/use-announcer";
import {
  draggable,
  dropTargetForElements,
  monitorForElements,
} from "@atlaskit/pragmatic-drag-and-drop/adapter/element-adapter";
import { dropTargetForExternal } from "@atlaskit/pragmatic-drag-and-drop/external/adapter";
import { containsFiles } from "@atlaskit/pragmatic-drag-and-drop/external/file";
import { combine } from "@atlaskit/pragmatic-drag-and-drop/utils/combine";
import { preserveOffsetOnSource } from "@atlaskit/pragmatic-drag-and-drop/element/preserve-offset-on-source";
import { setCustomNativeDragPreview } from "@atlaskit/pragmatic-drag-and-drop/element/set-custom-native-drag-preview";
import { attachClosestEdge } from "@atlaskit/pragmatic-drag-and-drop-hitbox/closest-edge/attach-closest-edge";
import { extractClosestEdge } from "@atlaskit/pragmatic-drag-and-drop-hitbox/closest-edge/extract-closest-edge";
import type { Edge } from "@atlaskit/pragmatic-drag-and-drop-hitbox/types";

/* ---
`use-drag-reorder` is the ONE file that owns drag engines. `useDragReorder` wraps
`@atlaskit/pragmatic-drag-and-drop` (sanctioned D3) for `sortable-list`; `usePointerDrag`
(below) is the live pointer gesture `board` runs on. An engine swap touches one module and its
tests. Pragmatic owns the pointer/touch drag lifecycle and hit-testing
(per-element drop targets + closest-edge, which cannot mis-target narrow columns the
way whole-surface collision detection can); everything the engine deliberately does
not own is implemented here, because it must match this system's interaction voice:

- the KEYBOARD layer — Space/Enter on the handle toggles move mode; arrows commit one
  reorder step at a time (each step lands in the host's state and is announced);
  Escape ends move mode. Commit-per-step follows Atlassian's own user-tested guidance
  (and their "Move to…" menu preference) rather than a ghost-position model: there is
  no virtual position to lose, the host's data is always the truth, and "cancel" is
  arrowing back. Consumers add their own non-drag path: board's "Move to…" menu, and
  sortable-list's touch long-press (on `usePointerDrag`) beside this keyboard mode.
- the LIVE REGION vocabulary — lifted / moved / dropped / move-ended / rejected, with
  overridable announcement builders.
- the ASYNC drop contract — `onReorder` may return a promise. While it is in flight
  the move is `pending` (consumers render the shimmer); on rejection the hook
  announces it and clears — the host never applied the move, so the snap-back is
  automatic. No drag library models refusable drops; the CRM's server-gated moves
  need it.

Deliberately NOT done here:
- No styling, no drag preview chrome. Consumers style off the returned state
  (`draggingId`, `closestEdge`, `pending`) with `data-*` attributes. The one DOM the hook
  makes is the native drag image: a plain copy of the item, clipped to the item's box, so a
  descendant positioned outside it (a Checkbox's fixed hidden input) cannot stretch the image.
- No optimistic insertion. The host owns ordering; optimistic UI is host state.
- No auto-scroll in `useDragReorder`. `edgeScroll` (below) is the helper `Board` calls each
  frame of a live drag.
--- */

/** Where an item sits: its container id and index within it. */
export interface DragReorderPosition {
  /** Container id (a single list uses the hook's default container). */
  container: string;
  /** Index within the container. */
  index: number;
}

/** One requested move — the payload `onReorder` receives. */
export interface DragReorderMove {
  /** The dragged item's id. */
  id: string;
  /** Where the item came from. */
  from: DragReorderPosition;
  /** Where the item should land. */
  to: DragReorderPosition;
  /** What initiated the move. */
  input: "pointer" | "keyboard" | "menu";
}

/** Overridable announcement builders for the live region. */
export interface DragReorderAnnouncements {
  /** Move mode entered on `id`. */
  lifted: (move: {
    id: string;
    position: number;
    count: number;
    container: string;
  }) => string;
  /** A step (keyboard) or drop (pointer) landed. */
  moved: (move: DragReorderMove & { count: number }) => string;
  /** Move mode ended (Space/Enter again, Escape, or blur). */
  ended: (move: { id: string }) => string;
  /** The host rejected the move (the `onReorder` promise rejected). */
  rejected: (move: DragReorderMove) => string;
}

const DEFAULT_ANNOUNCEMENTS: DragReorderAnnouncements = {
  lifted: ({ position, count }) =>
    `Move mode on. Item ${position} of ${count}. Use the arrow keys to move, Escape to finish`,
  moved: ({ to, count, from }) =>
    from.container === to.container
      ? `Moved to position ${to.index + 1} of ${count}`
      : `Moved to ${to.container}, position ${to.index + 1} of ${count}`,
  ended: () => "Move mode off",
  rejected: () => "Move rejected — position restored",
};

/** Options for {@link useDragReorder}. */
export interface UseDragReorderOptions {
  /**
   * Ordered item ids per container. A single list passes one entry (any key).
   * The hook never reorders this — it only requests moves via `onReorder`.
   */
  lists: Record<string, readonly string[]>;
  /**
   * Apply a move to host state. Return a promise for server-gated moves: the
   * move is `pending` until it settles, and a rejection announces + clears
   * (the host never applied it, so the visual snap-back is automatic).
   */
  onReorder: (move: DragReorderMove) => void | Promise<void>;
  /**
   * Axis items are ordered along inside a container. Drives the closest-edge
   * hitboxes and which arrow keys move within vs across containers.
   * @default "vertical"
   */
  axis?: "vertical" | "horizontal";
  /**
   * Row-aware vertical moves for a horizontal axis that WRAPS into a grid. With
   * `axis: "horizontal"`, ←/→ step one item in reading order and — when this is
   * set — ↑/↓ move the item one ROW (±`columns` places) within its container,
   * landing at the end when the row below is short. A number fixes the count;
   * `"auto"` measures it at key time from where the container's items wrap, so
   * a responsive `auto-fill` grid stays right at every width. Ignored on a
   * vertical axis. Without it, ↑/↓ on a horizontal axis move across
   * containers, as before.
   * @default undefined
   */
  columns?: number | "auto";
  /**
   * Disable all dragging and keyboard moves — statically, or per item.
   * @default false
   */
  disabled?: boolean | ((id: string) => boolean);
  /**
   * Disable the POINTER drag path only — the keyboard move mode and
   * `requestMove` keep working. This is the mobile posture: below the touch
   * breakpoint drags fight scrolling, but the lossless paths must survive.
   * @default false
   */
  pointerDisabled?: boolean;
  /**
   * Whether a container may receive drops (pointer path). Move-menu and
   * keyboard eligibility stay the CONSUMER'S concern — this only closes the
   * pointer hole where a locked container's items would still accept a drop.
   * @default undefined
   */
  canDropInContainer?: (container: string) => boolean;
  /**
   * Override the live-region announcement builders.

   * @default undefined
   */
  announcements?: Partial<DragReorderAnnouncements>;
}

/** What {@link useDragReorder} returns. */
export interface UseDragReorderReturn {
  /**
   * Register an item element (callback ref) as draggable + drop target.
   * `handle` optionally scopes dragging to a handle element registered via
   * `getHandleProps`' ref.
   */
  getItemProps: (
    container: string,
    id: string,
  ) => {
    ref: (element: HTMLElement | null) => void;
    "data-drag-item": string;
    "data-dragging": "" | undefined;
    "data-drop-edge": Edge | undefined;
    "data-drag-pending": "" | undefined;
  };
  /**
   * Keyboard move-mode handler props for the item's drag handle (an
   * icon `Button`). Space/Enter toggles move mode; arrows commit steps;
   * Escape ends.
   */
  getHandleProps: (
    container: string,
    id: string,
  ) => {
    ref: (element: HTMLElement | null) => void;
    onKeyDown: (event: React.KeyboardEvent<HTMLElement>) => void;
    onBlur: () => void;
    "aria-pressed": boolean;
  };
  /**
   * Call before running an item's own action (a row menu's "Delete", say). If the action
   * removes the item and focus falls to the page, focus moves to the handle of the item that
   * took its place (or the new last item) instead — or to that item's first control when it has
   * no handle (a locked row).
   */
  keepFocusAfter: (container: string, id: string) => void;
  /**
   * Register a container element as a drop target (needed so items can be
   * dropped into an EMPTY container).
   */
  getContainerProps: (container: string) => {
    ref: (element: HTMLElement | null) => void;
    "data-drop-container": string;
    "data-drop-over": "" | undefined;
  };
  /**
   * The polite live region every reorder announcement speaks through — the shared
   * `useAnnouncer` node. Render it once, anywhere inside the list.
   */
  Announcer: React.ComponentType<AnnouncerProps>;
  /** Id currently dragged by pointer, or in keyboard move mode. */
  activeId: string | null;
  /** The move currently awaiting its `onReorder` promise. */
  pending: DragReorderMove | null;
  /**
   * Programmatically request a move — the menu equivalent's entry point
   * (moves land with `input: "menu"`).
   */
  requestMove: (move: Omit<DragReorderMove, "input">) => void;
}

/**
 * Mount a copy of `element` into Pragmatic's preview `container`, at the item's own size and in
 * its inherited type, as the native drag image. The copy's box is a containing block for fixed
 * and absolute descendants (`contain: layout`) and clips at its edges, so nothing inside it can
 * stretch the image past the item.
 */
function renderItemPreview(element: HTMLElement, container: HTMLElement) {
  const rect = element.getBoundingClientRect();
  const inherited = element.parentElement
    ? getComputedStyle(element.parentElement)
    : null;
  const copy = element.cloneNode(true) as HTMLElement;
  // The copy is not a second item: no id to collide, no drag or drop hooks to find.
  for (const node of [copy, ...copy.querySelectorAll<HTMLElement>("[id]")])
    node.removeAttribute("id");
  copy.removeAttribute("data-drag-item");
  copy.removeAttribute("draggable");
  Object.assign(copy.style, {
    width: `${rect.width}px`,
    height: `${rect.height}px`,
    margin: "0",
    contain: "layout paint",
    boxSizing: "border-box",
    ...(inherited && {
      color: inherited.color,
      font: inherited.font,
      direction: inherited.direction,
    }),
  });
  container.append(copy);
  return () => copy.remove();
}

/**
 * The native drag image for a drag that is better named than pictured — several selected items
 * ("3 items"), or a table row, whose copy would lose its table. A small flat label in the
 * popover's own surface; every class is a literal so a consumer's Tailwind scanner sees it.
 */
function renderLabelPreview(label: string, container: HTMLElement) {
  const pill = document.createElement("div");
  pill.setAttribute("data-slot", "drag-preview");
  pill.className =
    "max-w-64 truncate rounded-md border border-border bg-popover px-2 py-1 text-sm text-popover-foreground";
  pill.textContent = label;
  container.append(pill);
  return () => pill.remove();
}

/** Locate an id across the lists. */
function positionOf(
  lists: Record<string, readonly string[]>,
  id: string,
): DragReorderPosition | null {
  for (const [container, ids] of Object.entries(lists)) {
    const index = ids.indexOf(id);
    if (index !== -1) return { container, index };
  }
  return null;
}

/**
 * `useDragReorder` — pointer/touch drag via Pragmatic drag-and-drop plus this
 * system's keyboard move mode, live-region vocabulary, and async
 * pending/rejected contract. One API covers a single list (`sortable-list`)
 * and cross-container boards; the host stays the owner of order.
 *
 * @example
 * const reorder = useDragReorder({
 *   lists: { list: ids },
 *   onReorder: ({ id, to }) => moveItem(id, to.index),
 * });
 * // <li {...reorder.getItemProps("list", id)}>
 * //   <Button size="icon-sm" aria-label={`Move ${label}`} {...reorder.getHandleProps("list", id)}>
 * //     <GripVertical />
 * //   </Button>
 * // </li>
 * // <reorder.Announcer />
 */
export function useDragReorder({
  lists,
  onReorder,
  axis = "vertical",
  columns,
  disabled = false,
  pointerDisabled = false,
  canDropInContainer,
  announcements,
}: UseDragReorderOptions): UseDragReorderReturn {
  const [activeId, setActiveId] = React.useState<string | null>(null);
  const [pending, setPending] = React.useState<DragReorderMove | null>(null);
  const [dropEdges, setDropEdges] = React.useState<Record<string, Edge>>({});
  const [overContainer, setOverContainer] = React.useState<string | null>(null);

  const announceRef = React.useRef<DragReorderAnnouncements>(
    DEFAULT_ANNOUNCEMENTS,
  );
  announceRef.current = { ...DEFAULT_ANNOUNCEMENTS, ...announcements };
  const listsRef = React.useRef(lists);
  listsRef.current = lists;
  const onReorderRef = React.useRef(onReorder);
  onReorderRef.current = onReorder;
  const disabledRef = React.useRef(disabled);
  disabledRef.current = disabled;
  const pointerDisabledRef = React.useRef(pointerDisabled);
  pointerDisabledRef.current = pointerDisabled;
  const canDropInContainerRef = React.useRef(canDropInContainer);
  canDropInContainerRef.current = canDropInContainer;
  const pendingSeq = React.useRef(0);

  const { announce, Announcer } = useAnnouncer();

  const isDisabled = React.useCallback((id: string) => {
    const value = disabledRef.current;
    return typeof value === "function" ? value(id) : value;
  }, []);

  /** Commit a move through the host, tracking the async contract. */
  const commitMove = React.useCallback(
    (move: DragReorderMove) => {
      const result = onReorderRef.current(move);
      const count = listsRef.current[move.to.container]?.length ?? 0;
      announce(announceRef.current.moved({ ...move, count }));
      if (result == null || typeof result.then !== "function") return;
      const seq = ++pendingSeq.current;
      setPending(move);
      result.then(
        () => {
          if (seq === pendingSeq.current) setPending(null);
        },
        () => {
          // A rejection is ALWAYS announced, even when a newer move has
          // superseded this one — the user must hear that the earlier move
          // did not land. Only the pending marker is seq-guarded.
          announce(announceRef.current.rejected(move));
          if (menuMoveFocusId.current === move.id)
            menuMoveFocusId.current = null;
          if (seq === pendingSeq.current) setPending(null);
        },
      );
    },
    [announce],
  );

  const requestMove = React.useCallback(
    (move: Omit<DragReorderMove, "input">) => {
      // A cross-container menu move remounts the item and unmounts the very
      // trigger the menu would restore focus to — arm a one-shot restore
      // that fires when the host applies the move (see the lists effect).
      menuMoveFocusId.current = move.id;
      commitMove({ ...move, input: "menu" });
    },
    [commitMove],
  );

  // One-shot focus restore for MENU moves, keyed on the host actually
  // applying the move (lists identity change). If focus survived (a
  // within-container move keeps the trigger mounted), do nothing; if it
  // fell to <body> (cross-container remount), put it on the moved item's
  // handle so the documented refine step stays keyboard-reachable.
  const menuMoveFocusId = React.useRef<string | null>(null);
  React.useEffect(() => {
    const id = menuMoveFocusId.current;
    if (id === null) return;
    menuMoveFocusId.current = null;
    const focused = document.activeElement;
    const fell =
      !(focused instanceof HTMLElement) ||
      focused === document.body ||
      !focused.isConnected;
    if (!fell) return;
    for (const [key, element] of handleElements.current) {
      if (key.endsWith(`:${id}`) && element.isConnected) {
        element.focus();
        break;
      }
    }
  }, [lists]);

  // ---- pointer path (Pragmatic) --------------------------------------------

  // The instance token scopes monitors so two hooks on one page never
  // cross-talk. A ref-stable symbol is identity enough.
  const instanceToken = React.useRef<symbol | null>(null);
  if (instanceToken.current === null)
    instanceToken.current = Symbol("use-drag-reorder");

  React.useEffect(() => {
    return monitorForElements({
      canMonitor: ({ source }) =>
        source.data.instance === instanceToken.current,
      onDrop: ({ source, location }) => {
        setActiveId(null);
        setDropEdges({});
        setOverContainer(null);
        const target = location.current.dropTargets[0];
        if (!target) return;
        const from = positionOf(listsRef.current, String(source.data.id));
        if (!from) return;
        let to: DragReorderPosition;
        if (target.data.kind === "container") {
          const container = String(target.data.container);
          // A container-level drop WITHIN the source's own container is a
          // no-op, not an append: it is what a drop on the dragged row
          // itself, or in the gap between rows, falls through to — treating
          // it as "send to the end" turns a 4px twitch into a reorder.
          // Dropping on ANOTHER container's empty area still appends.
          if (container === from.container) return;
          to = {
            container,
            index: listsRef.current[container]?.length ?? 0,
          };
        } else {
          const container = String(target.data.container);
          const targetIndex = Number(target.data.index);
          const edge = extractClosestEdge(target.data);
          let index =
            edge === "bottom" || edge === "right"
              ? targetIndex + 1
              : targetIndex;
          // Removing the item first shifts later indexes down within the
          // same container.
          if (from.container === container && from.index < index) index -= 1;
          to = { container, index };
        }
        if (to.container === from.container && to.index === from.index) return;
        commitMove({
          id: String(source.data.id),
          from,
          to,
          input: "pointer",
        });
      },
    });
  }, [commitMove]);

  const cleanups = React.useRef(new Map<string, () => void>());
  const handleElements = React.useRef(new Map<string, HTMLElement>());
  // Item elements by `${container}:${id}` — read to measure a wrapped grid's column count
  // (`columns: "auto"`), and (DS-70) so a handle that attaches or detaches AFTER its item can
  // rebuild the item's draggable around the current handle: Pragmatic reads `dragHandle` once.
  const itemElements = React.useRef(new Map<string, HTMLElement>());
  // Ref-callback identity MUST be stable per (container, id): React re-runs a
  // changed callback ref on every render (null → cleanup → re-attach), which
  // would tear down the ACTIVE draggable mid-drag the moment drop-edge state
  // re-renders the list. Cache one callback per key.
  const refCache = React.useRef(
    new Map<string, (element: HTMLElement | null) => void>(),
  );
  const axisRef = React.useRef(axis);
  axisRef.current = axis;

  const makeItemRef = React.useCallback(
    (container: string, id: string) => (element: HTMLElement | null) => {
      const key = `item:${container}:${id}`;
      cleanups.current.get(key)?.();
      cleanups.current.delete(key);
      if (!element) {
        itemElements.current.delete(`${container}:${id}`);
        return;
      }
      itemElements.current.set(`${container}:${id}`, element);
      const allowedEdges: Edge[] =
        axisRef.current === "vertical" ? ["top", "bottom"] : ["left", "right"];
      const cleanup = combine(
        draggable({
          element,
          dragHandle: handleElements.current.get(`${container}:${id}`),
          canDrag: () => !pointerDisabledRef.current && !isDisabled(id),
          // The browser sizes its own drag image from the item's box INCLUDING every
          // descendant's box — and a Base UI Checkbox or Switch without a `name` renders its
          // hidden input `position: fixed` at the viewport's top-left, which stretched the
          // image of a row with a "Required" checkbox to everything between the page's
          // corner and the row. The preview is a copy of the item alone instead.
          onGenerateDragPreview: ({ nativeSetDragImage, location }) =>
            setCustomNativeDragPreview({
              nativeSetDragImage,
              getOffset: preserveOffsetOnSource({
                element,
                input: location.current.input,
              }),
              render: ({ container }) => renderItemPreview(element, container),
            }),
          getInitialData: () => ({
            instance: instanceToken.current,
            id,
            container,
          }),
          onDragStart: () => {
            keyboardMoveSeq.current = 0;
            setActiveId(id);
            const position = positionOf(listsRef.current, id);
            if (position)
              announce(
                announceRef.current.lifted({
                  id,
                  position: position.index + 1,
                  count: listsRef.current[position.container]?.length ?? 0,
                  container: position.container,
                }),
              );
          },
          onDrop: () => setActiveId(null),
        }),
        dropTargetForElements({
          element,
          canDrop: ({ source }) =>
            source.data.instance === instanceToken.current &&
            source.data.id !== id &&
            (canDropInContainerRef.current?.(container) ?? true),
          getData: ({ input, element: el }) => {
            const index = listsRef.current[container]?.indexOf(id) ?? -1;
            return attachClosestEdge(
              { kind: "item", id, container, index },
              { element: el, input, allowedEdges },
            );
          },
          onDrag: ({ self }) => {
            const edge = extractClosestEdge(self.data);
            setDropEdges((prev) =>
              prev[id] === edge ? prev : edge ? { [id]: edge } : {},
            );
          },
          onDragLeave: () =>
            setDropEdges((prev) => {
              if (!(id in prev)) return prev;
              const next = { ...prev };
              delete next[id];
              return next;
            }),
          onDrop: () => setDropEdges({}),
        }),
      );
      cleanups.current.set(key, cleanup);
    },
    [announce, isDisabled],
  );
  const makeItemRefRef = React.useRef(makeItemRef);
  makeItemRefRef.current = makeItemRef;
  const registerItem = React.useCallback(
    (container: string, id: string) => {
      const key = `item-ref:${container}:${id}`;
      let cached = refCache.current.get(key);
      if (!cached) {
        const inner = makeItemRef(container, id);
        cached = (element: HTMLElement | null) => {
          inner(element);
          // React calls a ref with null only on detach — prune so a
          // long-lived board with card churn does not grow the cache
          // without bound. Identity stays stable across a mounted lifetime.
          if (element === null) refCache.current.delete(key);
        };
        refCache.current.set(key, cached);
      }
      return cached;
    },
    [makeItemRef],
  );

  const makeContainerRef = React.useCallback(
    (container: string) => (element: HTMLElement | null) => {
      const key = `container:${container}`;
      cleanups.current.get(key)?.();
      cleanups.current.delete(key);
      if (!element) return;
      const cleanup = dropTargetForElements({
        element,
        canDrop: ({ source }) =>
          source.data.instance === instanceToken.current &&
          (canDropInContainerRef.current?.(container) ?? true),
        getData: () => ({ kind: "container", container }),
        onDragEnter: () => setOverContainer(container),
        onDragLeave: () =>
          setOverContainer((prev) => (prev === container ? null : prev)),
        onDrop: () => setOverContainer(null),
      });
      cleanups.current.set(key, cleanup);
    },
    [],
  );
  const registerContainer = React.useCallback(
    (container: string) => {
      const key = `container-ref:${container}`;
      let cached = refCache.current.get(key);
      if (!cached) {
        const inner = makeContainerRef(container);
        cached = (element: HTMLElement | null) => {
          inner(element);
          if (element === null) refCache.current.delete(key);
        };
        refCache.current.set(key, cached);
      }
      return cached;
    },
    [makeContainerRef],
  );

  React.useEffect(() => {
    const map = cleanups.current;
    return () => {
      for (const cleanup of map.values()) cleanup();
      map.clear();
    };
  }, []);

  // ---- keyboard move mode (ours) -------------------------------------------

  // Counts keyboard steps in the CURRENT move session; zero outside one, so
  // the focus-restore effect below can never fire during a pointer drag.
  const keyboardMoveSeq = React.useRef(0);

  const endMoveMode = React.useCallback(
    (id: string) => {
      keyboardMoveSeq.current = 0;
      setActiveId((prev) => {
        if (prev !== id) return prev;
        announce(announceRef.current.ended({ id }));
        return null;
      });
    },
    [announce],
  );

  /**
   * Items per row in `container`: the fixed `columns`, or — for `"auto"` — how
   * many leading items share the first item's row (their top edges agree
   * within a pixel). Falls back to 1 when nothing is measurable.
   */
  const columnsIn = React.useCallback(
    (container: string): number => {
      if (typeof columns === "number") return Math.max(1, Math.floor(columns));
      const ids = listsRef.current[container] ?? [];
      let firstTop: number | null = null;
      let count = 0;
      for (const itemId of ids) {
        const element = itemElements.current.get(`${container}:${itemId}`);
        if (!element) break;
        const top = element.getBoundingClientRect().top;
        if (firstTop === null) firstTop = top;
        else if (Math.abs(top - firstTop) > 1) break;
        count += 1;
      }
      return Math.max(1, count);
    },
    [columns],
  );

  const handleKeyDown = React.useCallback(
    (container: string, id: string, event: React.KeyboardEvent) => {
      if (isDisabled(id)) return;
      const inMoveMode = activeId === id;
      if (event.key === " " || event.key === "Enter") {
        event.preventDefault();
        if (inMoveMode) {
          endMoveMode(id);
        } else {
          setActiveId(id);
          const position = positionOf(listsRef.current, id);
          if (position)
            announce(
              announceRef.current.lifted({
                id,
                position: position.index + 1,
                count: listsRef.current[position.container]?.length ?? 0,
                container: position.container,
              }),
            );
        }
        return;
      }
      if (!inMoveMode) return;
      if (event.key === "Escape") {
        event.preventDefault();
        endMoveMode(id);
        return;
      }
      const from = positionOf(listsRef.current, id);
      if (!from) return;
      // Horizontal arrows must follow the document direction — browsing
      // focus already does, and move mode may not disagree with it.
      const rtl =
        getComputedStyle(event.currentTarget as HTMLElement).direction ===
        "rtl";
      const flip = (key: string) =>
        rtl && (key === "ArrowLeft" || key === "ArrowRight")
          ? key === "ArrowLeft"
            ? "ArrowRight"
            : "ArrowLeft"
          : key;
      const withinPrev = flip(axis === "vertical" ? "ArrowUp" : "ArrowLeft");
      const withinNext = flip(axis === "vertical" ? "ArrowDown" : "ArrowRight");
      const acrossPrev = flip(axis === "vertical" ? "ArrowLeft" : "ArrowUp");
      const acrossNext = flip(axis === "vertical" ? "ArrowRight" : "ArrowDown");
      const containers = Object.keys(listsRef.current);
      // A wrapped horizontal list (a grid): ↑/↓ move one ROW within the
      // container. Clamp into a short last row, but never "move" within the
      // row the item already sits on — that is ←/→'s job.
      if (
        axis === "horizontal" &&
        columns !== undefined &&
        (event.key === "ArrowUp" || event.key === "ArrowDown")
      ) {
        event.preventDefault();
        const perRow = columnsIn(from.container);
        const count = listsRef.current[from.container]?.length ?? 0;
        const target = Math.max(
          0,
          Math.min(
            from.index + (event.key === "ArrowUp" ? -perRow : perRow),
            count - 1,
          ),
        );
        if (Math.floor(target / perRow) === Math.floor(from.index / perRow))
          return;
        keyboardMoveSeq.current += 1;
        commitMove({
          id,
          from,
          to: { container: from.container, index: target },
          input: "keyboard",
        });
        return;
      }
      if (event.key === withinPrev || event.key === withinNext) {
        event.preventDefault();
        const delta = event.key === withinPrev ? -1 : 1;
        const count = listsRef.current[from.container]?.length ?? 0;
        const index = Math.max(0, Math.min(from.index + delta, count - 1));
        if (index === from.index) return;
        keyboardMoveSeq.current += 1;
        commitMove({
          id,
          from,
          to: { container: from.container, index },
          input: "keyboard",
        });
      } else if (
        (event.key === acrossPrev || event.key === acrossNext) &&
        containers.length > 1
      ) {
        event.preventDefault();
        const delta = event.key === acrossPrev ? -1 : 1;
        const containerIndex = containers.indexOf(from.container);
        const next = containers[containerIndex + delta];
        if (next === undefined) return;
        const count = listsRef.current[next]?.length ?? 0;
        keyboardMoveSeq.current += 1;
        commitMove({
          id,
          from,
          to: { container: next, index: Math.min(from.index, count) },
          input: "keyboard",
        });
      }
    },
    [
      activeId,
      axis,
      columns,
      columnsIn,
      announce,
      commitMove,
      endMoveMode,
      isDisabled,
    ],
  );

  // An item action that removes its own item takes the focused menu with it. After the commit,
  // focus the handle now at its place (or the new last one) — but only if focus fell to the page,
  // and only for an item whose action asked for it, so a poll never steals focus.
  const refocus = React.useRef<{
    container: string;
    id: string;
    index: number;
  } | null>(null);
  React.useEffect(() => {
    const target = refocus.current;
    if (!target) return;
    const ids = listsRef.current[target.container] ?? [];
    if (ids.includes(target.id)) {
      // Not removed: the menu hands focus back to its trigger as usual.
      if (document.activeElement !== document.body) refocus.current = null;
      return;
    }
    refocus.current = null;
    const focused = document.activeElement;
    if (focused instanceof HTMLElement && focused !== document.body) return;
    const next = ids[Math.min(target.index, ids.length - 1)];
    if (next === undefined) return;
    const key = `${target.container}:${next}`;
    // A locked row renders no handle; its first control (its menu trigger) takes focus instead.
    (
      handleElements.current.get(key) ??
      itemElements.current
        .get(key)
        ?.querySelector<HTMLElement>(
          'button:not(:disabled), a[href], [tabindex]:not([tabindex="-1"])',
        )
    )?.focus();
  });

  // A cross-container keyboard move REMOUNTS the item under its new parent;
  // React fires no blur for an unmounted node, so move mode survives — but
  // focus lands on <body> and the session dies. After every render while a
  // keyboard move session is live, put focus back on the item's handle if it
  // fell off. Same-parent moves keep their node and are unaffected.
  React.useEffect(() => {
    if (activeId === null || keyboardMoveSeq.current === 0) return;
    const focused = document.activeElement;
    let handle: HTMLElement | null = null;
    for (const [key, element] of handleElements.current) {
      if (key.endsWith(`:${activeId}`) && element.isConnected) {
        handle = element;
        break;
      }
    }
    if (!handle || focused === handle) return;
    if (focused instanceof HTMLElement && focused !== document.body) return;
    handle.focus();
  });

  const registerHandle = React.useCallback((container: string, id: string) => {
    const key = `handle-ref:${container}:${id}`;
    let cached = refCache.current.get(key);
    if (!cached) {
      cached = (element: HTMLElement | null) => {
        const mapKey = `${container}:${id}`;
        if (element) {
          handleElements.current.set(mapKey, element);
        } else {
          handleElements.current.delete(mapKey);
          // Same bounded-cache rule as items: prune on detach so container
          // and card churn cannot grow the cache without bound.
          refCache.current.delete(key);
        }
        // DS-70: a handle that mounts after its item (a row switched from disabled to enabled,
        // say) would otherwise never own the drag — the draggable was built without it, so the
        // whole row dragged. Rebuild the item's draggable around the handle as it is now.
        const item = itemElements.current.get(mapKey);
        if (item) makeItemRefRef.current(container, id)(item);
      };
      refCache.current.set(key, cached);
    }
    return cached;
  }, []);

  return {
    getItemProps: (container, id) => ({
      ref: registerItem(container, id),
      "data-drag-item": id,
      "data-dragging": activeId === id ? "" : undefined,
      "data-drop-edge": dropEdges[id],
      "data-drag-pending": pending?.id === id ? "" : undefined,
    }),
    getHandleProps: (container, id) => ({
      ref: registerHandle(container, id),
      onKeyDown: (event) => handleKeyDown(container, id, event),
      onBlur: () => endMoveMode(id),
      "aria-pressed": activeId === id,
    }),
    keepFocusAfter: (container, id) => {
      refocus.current = {
        container,
        id,
        index: listsRef.current[container]?.indexOf(id) ?? 0,
      };
    },
    getContainerProps: (container) => ({
      ref: registerContainer(container),
      "data-drop-container": container,
      "data-drop-over": overContainer === container ? "" : undefined,
    }),
    Announcer,
    activeId,
    pending,
    requestMove,
  };
}

// ---------------------------------------------------------------------------------------------
// Live pointer drag (ours) — the engine `Board` runs on.
// ---------------------------------------------------------------------------------------------

/* ---
`usePointerDrag` is the second engine in this file, and the one `Board` uses. Pragmatic drives the
browser's native drag, whose preview is a flat bitmap the page cannot move, tilt, shadow or settle,
and whose touch support is whatever each browser's long-press happens to do. A board card needs a
LIVE drag: the card lifts under the finger, the cards around it make room, and it settles into its
slot. That takes pointer events, so this hook owns only the gesture — when a drag starts, where the
pointer is each frame, when it ends — and hands geometry to the host, which owns hit-testing and
rendering (it knows its lanes; the hook does not).

- Mouse and pen: a drag starts after the pointer travels `threshold` px with the button held, so a
  click stays a click.
- Touch: a drag starts after a `longPressMs` hold (250ms) that moves less than 8px; any earlier
  movement is a swipe and scrolls the page as usual. `navigator.vibrate` marks the lift where the
  device supports it. While a touch drag is live, `touchmove` is cancelled so the page does not
  scroll under the finger, and the long-press context menu is suppressed.
- `onFrame` fires every animation frame while dragging — the host auto-scrolls and re-hit-tests
  there, because a scrolling lane moves cards under a still pointer.
- The click that ends a mouse drag is swallowed, so dropping a link card never follows the link.
- Escape cancels.
--- */

/** A pointer position in viewport coordinates. */
export interface PointerDragPoint {
  x: number;
  y: number;
}

/** Options for {@link usePointerDrag}. */
export interface UsePointerDragOptions {
  /**
   * Refuse every drag.
   * @default false
   */
  disabled?: boolean;
  /**
   * Hold time before a touch drag starts, in ms.
   * @default 250
   */
  longPressMs?: number;
  /**
   * Distance a mouse or pen must travel before a drag starts, in px.
   * @default 4
   */
  threshold?: number;
  /**
   * A drag is starting on `element` for item `id`. Return `false` to refuse it.
   */
  onStart: (
    id: string,
    element: HTMLElement,
    point: PointerDragPoint,
    pointerType: string,
  ) => boolean | void;
  /** Every animation frame while dragging, with the latest pointer position. */
  onFrame: (point: PointerDragPoint) => void;
  /** The pointer was released over `point`. */
  onDrop: (point: PointerDragPoint) => void;
  /** The drag was cancelled (Escape, or the browser took the pointer). */
  onCancel: () => void;
}

/** What {@link usePointerDrag} returns. */
export interface UsePointerDragReturn {
  /** Props for a draggable element. Interactive descendants (buttons, links, checkboxes, inputs)
   * never start a drag, except an element marked `data-drag-surface`. */
  getSourceProps: (id: string) => {
    onPointerDown: (event: React.PointerEvent<HTMLElement>) => void;
    onContextMenu: (event: React.MouseEvent<HTMLElement>) => void;
    onDragStart: (event: React.DragEvent<HTMLElement>) => void;
  };
  /** Whether a drag is live. */
  dragging: boolean;
}

const INTERACTIVE_DESCENDANT =
  'button, a, input, textarea, select, label, [role="checkbox"], [role="switch"], [role="menuitem"], [data-no-drag]';

/**
 * `usePointerDrag` — the live pointer drag gesture: threshold drags for mouse and pen, a 250ms
 * long-press for touch, a per-frame callback for auto-scroll and hit-testing, and Escape to
 * cancel. The host renders the lifted card and the gap; this hook only tracks the pointer.
 *
 * @example
 * const drag = usePointerDrag({
 *   onStart: (id, element, point) => lift(id, element, point),
 *   onFrame: (point) => follow(point),
 *   onDrop: (point) => settle(point),
 *   onCancel: () => reset(),
 * });
 * // <div {...drag.getSourceProps(card.id)}>…</div>
 */
export function usePointerDrag({
  disabled = false,
  longPressMs = 250,
  threshold = 4,
  onStart,
  onFrame,
  onDrop,
  onCancel,
}: UsePointerDragOptions): UsePointerDragReturn {
  const [dragging, setDragging] = React.useState(false);
  const callbacks = React.useRef({ onStart, onFrame, onDrop, onCancel });
  callbacks.current = { onStart, onFrame, onDrop, onCancel };
  const session = React.useRef<{
    id: string;
    element: HTMLElement;
    pointerId: number;
    pointerType: string;
    start: PointerDragPoint;
    point: PointerDragPoint;
    active: boolean;
    timer: ReturnType<typeof setTimeout> | null;
    frame: number | null;
    teardown: () => void;
  } | null>(null);

  const end = React.useCallback((how: "drop" | "cancel" | "abort") => {
    const current = session.current;
    if (!current) return;
    session.current = null;
    if (current.timer) clearTimeout(current.timer);
    if (current.frame !== null) cancelAnimationFrame(current.frame);
    current.teardown();
    if (!current.active) return;
    setDragging(false);
    if (how === "drop") {
      callbacks.current.onDrop(current.point);
      // The click that follows a mouse drag must not activate the card (or follow its link).
      const swallow = (event: MouseEvent) => {
        event.preventDefault();
        event.stopPropagation();
      };
      window.addEventListener("click", swallow, { capture: true, once: true });
      setTimeout(
        () => window.removeEventListener("click", swallow, { capture: true }),
        0,
      );
    } else {
      callbacks.current.onCancel();
    }
  }, []);

  React.useEffect(() => () => end("abort"), [end]);

  const activate = React.useCallback(() => {
    const current = session.current;
    if (!current || current.active) return;
    const accepted = callbacks.current.onStart(
      current.id,
      current.element,
      current.point,
      current.pointerType,
    );
    if (accepted === false) {
      end("abort");
      return;
    }
    current.active = true;
    setDragging(true);
    if (current.pointerType === "touch" && typeof navigator !== "undefined")
      navigator.vibrate?.(10);
    const tick = () => {
      const live = session.current;
      if (!live || !live.active) return;
      callbacks.current.onFrame(live.point);
      live.frame = requestAnimationFrame(tick);
    };
    current.frame = requestAnimationFrame(tick);
  }, [end]);

  const onPointerDown = React.useCallback(
    (id: string, event: React.PointerEvent<HTMLElement>) => {
      if (disabled || session.current) return;
      if (event.pointerType === "mouse" && event.button !== 0) return;
      const target = event.target as HTMLElement;
      const interactive = target.closest<HTMLElement>(INTERACTIVE_DESCENDANT);
      if (
        interactive &&
        event.currentTarget.contains(interactive) &&
        !interactive.hasAttribute("data-drag-surface")
      )
        return;
      const element = event.currentTarget;
      const point = { x: event.clientX, y: event.clientY };
      const pointerType = event.pointerType;
      const onMove = (move: PointerEvent) => {
        const current = session.current;
        if (!current || move.pointerId !== current.pointerId) return;
        current.point = { x: move.clientX, y: move.clientY };
        if (current.active) return;
        const distance = Math.hypot(
          current.point.x - current.start.x,
          current.point.y - current.start.y,
        );
        if (current.pointerType === "touch") {
          // Moving before the hold completes is a swipe: let the page scroll.
          if (distance > 8) end("abort");
        } else if (distance >= threshold) {
          activate();
        }
      };
      const onUp = (up: PointerEvent) => {
        if (session.current && up.pointerId === session.current.pointerId)
          end("drop");
      };
      const onPointerCancel = (cancel: PointerEvent) => {
        if (session.current && cancel.pointerId === session.current.pointerId)
          end("cancel");
      };
      const onKey = (key: KeyboardEvent) => {
        if (key.key === "Escape" && session.current?.active) {
          key.preventDefault();
          end("cancel");
        }
      };
      // A live touch drag owns the finger: the page must not scroll under it.
      const onTouchMove = (touch: TouchEvent) => {
        if (session.current?.active) touch.preventDefault();
      };
      window.addEventListener("pointermove", onMove);
      window.addEventListener("pointerup", onUp);
      window.addEventListener("pointercancel", onPointerCancel);
      window.addEventListener("keydown", onKey);
      window.addEventListener("touchmove", onTouchMove, { passive: false });
      session.current = {
        id,
        element,
        pointerId: event.pointerId,
        pointerType,
        start: point,
        point,
        active: false,
        timer:
          pointerType === "touch" ? setTimeout(activate, longPressMs) : null,
        frame: null,
        teardown: () => {
          window.removeEventListener("pointermove", onMove);
          window.removeEventListener("pointerup", onUp);
          window.removeEventListener("pointercancel", onPointerCancel);
          window.removeEventListener("keydown", onKey);
          window.removeEventListener("touchmove", onTouchMove);
        },
      };
    },
    [activate, disabled, end, longPressMs, threshold],
  );

  return {
    getSourceProps: (id) => ({
      onPointerDown: (event) => onPointerDown(id, event),
      // The long-press menu (copy, open in new tab) would steal a touch drag.
      onContextMenu: (event) => {
        if (session.current) event.preventDefault();
      },
      // A link card must never start the browser's own drag.
      onDragStart: (event) => event.preventDefault(),
    }),
    dragging,
  };
}

/**
 * Scroll `element` toward the pointer when it is within `edge` px of one of its edges on `axis`,
 * faster the closer it is. Returns whether it scrolled.
 */
export function edgeScroll(
  element: HTMLElement,
  point: PointerDragPoint,
  axis: "x" | "y",
  edge = 48,
  maxSpeed = 16,
): boolean {
  const rect = element.getBoundingClientRect();
  const start = axis === "x" ? rect.left : rect.top;
  const end = axis === "x" ? rect.right : rect.bottom;
  const position = axis === "x" ? point.x : point.y;
  const cross = axis === "x" ? point.y : point.x;
  const crossStart = axis === "x" ? rect.top : rect.left;
  const crossEnd = axis === "x" ? rect.bottom : rect.right;
  if (cross < crossStart || cross > crossEnd) return false;
  let delta = 0;
  const ratio = (distance: number) => Math.min(1, distance / edge);
  if (position < start + edge)
    delta = -Math.ceil(ratio(start + edge - position) * maxSpeed);
  else if (position > end - edge)
    delta = Math.ceil(ratio(position - (end - edge)) * maxSpeed);
  if (delta === 0) return false;
  const before = axis === "x" ? element.scrollLeft : element.scrollTop;
  if (axis === "x") element.scrollLeft += delta;
  else element.scrollTop += delta;
  return (axis === "x" ? element.scrollLeft : element.scrollTop) !== before;
}

// ---- drag INTO (trees) ----------------------------------------------------------------------

/** One requested move into a target — the payload `useDragInto`'s `onDrop` receives. */
export interface DragIntoMove {
  /**
   * The dragged item ids: the item itself, or every id `getDragIds` returned for it (a
   * multi-select drag).
   */
  ids: string[];
  /** The key of the target the items were dropped into. */
  targetKey: string;
}

/**
 * One desktop file dropped on a `useDragInto` target, with its path inside the drop — the same
 * shape as `use-file-drop`'s `FileDropEntry`, so one upload callback serves both.
 */
export interface DragIntoFileEntry {
  /** The dropped file. */
  file: File;
  /**
   * Its path relative to the drop: `"a/c/d.png"` for a file inside a dropped folder `a`, the bare
   * name for a loose file. Forward slashes, no leading `/`.
   */
  relativePath: string;
}

/** Desktop files dropped on a target — the payload `useDragInto`'s `onDropFiles` receives. */
export interface DragIntoFileDrop {
  /** The key of the target the files were dropped on. */
  targetKey: string;
  /** Every dropped file, folders walked. */
  entries: DragIntoFileEntry[];
}

/**
 * Marks a native `drop` a `useDragInto` target took, so an outer `useFileDrop` surface ignores it
 * (a registry symbol: the two hooks share it without importing each other).
 */
const FILE_DROP_CLAIMED = Symbol.for("vegastack/file-drop-claimed");

/** Read a file entry. */
function fileOf(entry: FileSystemFileEntry): Promise<File> {
  return new Promise((resolve, reject) => entry.file(resolve, reject));
}

/** Every entry of a directory (`readEntries` returns them in batches). */
async function childrenOf(
  entry: FileSystemDirectoryEntry,
): Promise<FileSystemEntry[]> {
  const reader = entry.createReader();
  const out: FileSystemEntry[] = [];
  for (;;) {
    const batch = await new Promise<FileSystemEntry[]>((resolve, reject) =>
      reader.readEntries(resolve, reject),
    );
    if (batch.length === 0) return out;
    out.push(...batch);
  }
}

/**
 * The dropped files with their paths, folders walked. The entries are taken synchronously — a
 * drop's items are gone once its event ends — and read afterwards.
 */
function readDroppedEntries(
  items: readonly DataTransferItem[],
): Promise<DragIntoFileEntry[]> {
  const roots = items
    .filter((item) => item.kind === "file")
    .map((item) => ({
      entry: item.webkitGetAsEntry?.() ?? null,
      file: item.getAsFile(),
    }));
  const walk = async (entry: FileSystemEntry): Promise<DragIntoFileEntry[]> => {
    if (entry.isFile) {
      const file = await fileOf(entry as FileSystemFileEntry);
      return [
        { file, relativePath: entry.fullPath.replace(/^\/+/, "") || file.name },
      ];
    }
    if (!entry.isDirectory) return [];
    const nested = await Promise.all(
      (await childrenOf(entry as FileSystemDirectoryEntry)).map(walk),
    );
    return nested.flat();
  };
  return Promise.all(
    roots.map(({ entry, file }) =>
      entry
        ? walk(entry)
        : Promise.resolve(file ? [{ file, relativePath: file.name }] : []),
    ),
  ).then((lists) => lists.flat());
}

/** The ids a `useDragInto` source carries (older sources carry only `id`). */
function idsOf(data: Record<string | symbol, unknown>): string[] {
  return Array.isArray(data.ids) ? data.ids.map(String) : [String(data.id)];
}

/** Options for {@link useDragInto}. */
export interface UseDragIntoOptions {
  /** Apply a move. Called only for a valid drop inside a target's inside zone. */
  onDrop: (move: DragIntoMove) => void;
  /**
   * Whether a move is allowed. An invalid target still shows the drag (as
   * `data-drop-invalid`) but refuses the drop.
   * @default undefined
   */
  canDrop?: (move: DragIntoMove) => boolean;
  /**
   * Called once when a drag has hovered a target's inside zone for `hoverExpandDelay` — the tree
   * expands a collapsed folder here.
   * @default undefined
   */
  onHoverExpand?: (targetKey: string) => void;
  /**
   * How long a drag rests on a target before `onHoverExpand`, in milliseconds.
   * @default 600
   */
  hoverExpandDelay?: number;
  /**
   * Disable every source and target.
   * @default false
   */
  disabled?: boolean;
  /**
   * Share drags across hook instances: every `useDragInto` with the same `scope` accepts the
   * others' sources on its targets, so a list's rows can drop onto a breadcrumb or a tree that
   * owns its own hook. Without it only this instance's sources reach its targets.
   * @default undefined
   */
  scope?: string;
  /**
   * The ids a drag of `id` carries — the whole selection when `id` is selected. The target's
   * `canDrop`/`onDrop` receive them as `ids`.
   * @default (id) => [id]
   */
  getDragIds?: (id: string) => string[];
  /**
   * Name the drag instead of picturing it: return a label ("3 items", a row's name) and the
   * native drag image is that label; return `undefined` to use a copy of the item.
   * @default undefined
   */
  getDragPreviewLabel?: (ids: string[]) => string | undefined;
  /**
   * Desktop files dropped on a target. With it every drop target also takes files dragged in from
   * the desktop — the same zone, `data-drop-over` wash and hover-expand as an item drag — and
   * folders keep their structure in each entry's `relativePath`. The innermost target takes the
   * drop: an outer `useFileDrop` surface ignores it.
   * @default undefined
   */
  onDropFiles?: (drop: DragIntoFileDrop) => void;
  /**
   * Called with the target desktop files are over (inside its zone), and `null` when they leave
   * it or drop — for naming the destination in the host's own drop hint.
   * @default undefined
   */
  onFilesOver?: (targetKey: string | null) => void;
}

/** What {@link useDragInto} returns. */
export interface UseDragIntoReturn {
  /**
   * Register one element (a callback ref plus its state flags) as a drag source (`drag`), a drop
   * target (`drop`), or both. `drop: "middle"` takes a drop only in the middle half of the
   * element — its top and bottom quarters are ignored, so a drag across a list of rows does not
   * flicker; `"whole"` takes it anywhere (a section heading).
   */
  getItemProps: (
    key: string,
    options: { drag?: boolean; drop?: "middle" | "whole" | false },
  ) => {
    ref: (element: HTMLElement | null) => void;
    "data-dragging": "" | undefined;
    "data-drop-over": "" | undefined;
    "data-drop-invalid": "" | undefined;
  };
  /** The id being dragged, or `null`. */
  draggingId: string | null;
}

/**
 * `useDragInto` — drag an item INTO a target, the move a folder tree makes. Pointer only, on the
 * same Pragmatic engine as `useDragReorder`; a target takes a drop in its middle half, an invalid
 * target shows `data-drop-invalid` and refuses, and resting on a target calls `onHoverExpand`.
 * The keyboard path is the host's "Move…" menu: there is no order to step through. With
 * `onDropFiles` the targets also take files dragged in from the desktop.
 *
 * @example
 * const into = useDragInto({
 *   canDrop: ({ ids, targetKey }) => !ids.includes(targetKey),
 *   onDrop: ({ ids, targetKey }) => moveInto(ids, targetKey),
 *   onHoverExpand: (key) => expand(key),
 * });
 * // <div {...into.getItemProps(id, { drag: true, drop: isFolder && "middle" })}>…</div>
 */
export function useDragInto({
  onDrop,
  canDrop,
  onHoverExpand,
  hoverExpandDelay = 600,
  disabled = false,
  scope,
  getDragIds,
  getDragPreviewLabel,
  onDropFiles,
  onFilesOver,
}: UseDragIntoOptions): UseDragIntoReturn {
  const [draggingId, setDraggingId] = React.useState<string | null>(null);
  const [over, setOver] = React.useState<{
    key: string;
    valid: boolean;
  } | null>(null);
  const latest = React.useRef({
    onDrop,
    canDrop,
    onHoverExpand,
    disabled,
    getDragIds,
    getDragPreviewLabel,
    onDropFiles,
    onFilesOver,
  });
  latest.current = {
    onDrop,
    canDrop,
    onHoverExpand,
    disabled,
    getDragIds,
    getDragPreviewLabel,
    onDropFiles,
    onFilesOver,
  };
  // The target desktop files are over, reported through `onFilesOver` on every change.
  const filesOverRef = React.useRef<string | null>(null);
  const setFilesOver = React.useCallback((key: string | null) => {
    if (filesOverRef.current === key) return;
    filesOverRef.current = key;
    latest.current.onFilesOver?.(key);
  }, []);
  const delayRef = React.useRef(hoverExpandDelay);
  delayRef.current = hoverExpandDelay;
  const instanceToken = React.useRef<symbol | null>(null);
  if (instanceToken.current === null)
    instanceToken.current = Symbol("use-drag-into");
  // A scope is a registry symbol, so every instance naming it reads the same token.
  const tokenRef = React.useRef<symbol>(instanceToken.current);
  tokenRef.current =
    scope !== undefined
      ? Symbol.for(`vegastack/use-drag-into:${scope}`)
      : instanceToken.current;
  const hoverTimer = React.useRef<{
    key: string;
    timer: ReturnType<typeof setTimeout>;
  } | null>(null);

  const clearHover = React.useCallback(() => {
    if (hoverTimer.current) clearTimeout(hoverTimer.current.timer);
    hoverTimer.current = null;
  }, []);

  React.useEffect(() => clearHover, [clearHover]);

  const cleanups = React.useRef(new Map<string, () => void>());
  // One callback ref per (key, options): React re-runs a changed callback ref on every render,
  // which would tear the ACTIVE draggable down mid-drag.
  const refCache = React.useRef(
    new Map<string, (element: HTMLElement | null) => void>(),
  );

  const attach = React.useCallback(
    (
      element: HTMLElement,
      key: string,
      drag: boolean,
      drop: "middle" | "whole" | false,
    ) => {
      const parts: Array<() => void> = [];
      if (drag)
        parts.push(
          draggable({
            element,
            canDrag: () => !latest.current.disabled,
            onGenerateDragPreview: ({
              nativeSetDragImage,
              location,
              source,
            }) => {
              const label = latest.current.getDragPreviewLabel?.(
                idsOf(source.data),
              );
              setCustomNativeDragPreview({
                nativeSetDragImage,
                getOffset:
                  label === undefined
                    ? preserveOffsetOnSource({
                        element,
                        input: location.current.input,
                      })
                    : () => ({ x: 12, y: 12 }),
                render: ({ container }) =>
                  label === undefined
                    ? renderItemPreview(element, container)
                    : renderLabelPreview(label, container),
              });
            },
            getInitialData: () => {
              const ids = latest.current.getDragIds?.(key) ?? [key];
              return {
                instance: tokenRef.current,
                id: key,
                ids: ids.includes(key) ? ids : [key, ...ids],
              };
            },
            onDragStart: () => setDraggingId(key),
            onDrop: () => {
              setDraggingId(null);
              setOver(null);
              clearHover();
            },
          }),
        );
      if (drop) {
        /** Where the pointer is: inside the zone, and whether the move is allowed there. */
        const read = (
          source: { data: Record<string | symbol, unknown> },
          input: { clientY: number },
        ) => {
          const rect = element.getBoundingClientRect();
          const y = input.clientY - rect.top;
          const inside =
            drop === "whole" ||
            (y >= rect.height * 0.25 && y <= rect.height * 0.75);
          const move: DragIntoMove = {
            ids: idsOf(source.data),
            targetKey: key,
          };
          const valid =
            !move.ids.includes(key) && (latest.current.canDrop?.(move) ?? true);
          return { inside, valid, move };
        };
        const track = (inside: boolean, valid: boolean) => {
          setOver((prev) =>
            !inside
              ? prev?.key === key
                ? null
                : prev
              : prev?.key === key && prev.valid === valid
                ? prev
                : { key, valid },
          );
          if (inside && valid) {
            if (hoverTimer.current?.key !== key) {
              clearHover();
              hoverTimer.current = {
                key,
                timer: setTimeout(() => {
                  hoverTimer.current = null;
                  latest.current.onHoverExpand?.(key);
                }, delayRef.current),
              };
            }
          } else if (hoverTimer.current?.key === key) clearHover();
        };
        parts.push(
          dropTargetForElements({
            element,
            canDrop: ({ source }) =>
              !latest.current.disabled &&
              source.data.instance === tokenRef.current,
            onDragEnter: ({ source, location }) => {
              const { inside, valid } = read(source, location.current.input);
              track(inside, valid);
            },
            onDrag: ({ source, location }) => {
              const { inside, valid } = read(source, location.current.input);
              track(inside, valid);
            },
            onDragLeave: () => {
              setOver((prev) => (prev?.key === key ? null : prev));
              if (hoverTimer.current?.key === key) clearHover();
            },
            onDrop: ({ source, location }) => {
              const { inside, valid, move } = read(
                source,
                location.current.input,
              );
              setOver(null);
              clearHover();
              if (inside && valid) latest.current.onDrop(move);
            },
          }),
        );
        // Desktop files: the same zone and wash, taken by the innermost target only.
        let claimed = false;
        const readFiles = (location: {
          current: {
            input: { clientY: number };
            dropTargets: ReadonlyArray<{ element: Element }>;
          };
        }) => {
          const rect = element.getBoundingClientRect();
          const y = location.current.input.clientY - rect.top;
          return (
            location.current.dropTargets[0]?.element === element &&
            (drop === "whole" ||
              (y >= rect.height * 0.25 && y <= rect.height * 0.75))
          );
        };
        const trackFiles = (inside: boolean) => {
          track(inside, true);
          if (inside) setFilesOver(key);
          else if (filesOverRef.current === key) setFilesOver(null);
        };
        parts.push(
          dropTargetForExternal({
            element,
            canDrop: ({ source }) =>
              !latest.current.disabled &&
              latest.current.onDropFiles !== undefined &&
              containsFiles({ source }),
            onDragEnter: ({ location }) => trackFiles(readFiles(location)),
            onDrag: ({ location }) => trackFiles(readFiles(location)),
            onDragLeave: () => {
              setOver((prev) => (prev?.key === key ? null : prev));
              if (hoverTimer.current?.key === key) clearHover();
              if (filesOverRef.current === key) setFilesOver(null);
            },
            onDrop: ({ source, location }) => {
              const inside = readFiles(location);
              setOver((prev) => (prev?.key === key ? null : prev));
              clearHover();
              if (filesOverRef.current === key) setFilesOver(null);
              const handler = latest.current.onDropFiles;
              if (!inside || !handler) return;
              // The native `drop` reaches this element after Pragmatic's window listener: mark
              // it there, so an outer file-drop surface leaves it alone.
              claimed = true;
              void readDroppedEntries(source.items).then((entries) => {
                if (entries.length > 0) handler({ targetKey: key, entries });
              });
            },
          }),
        );
        const markClaimed = (event: DragEvent) => {
          if (!claimed) return;
          claimed = false;
          (event as DragEvent & { [FILE_DROP_CLAIMED]?: boolean })[
            FILE_DROP_CLAIMED
          ] = true;
        };
        element.addEventListener("drop", markClaimed);
        parts.push(() => element.removeEventListener("drop", markClaimed));
      }
      return combine(...parts);
    },
    [clearHover, setFilesOver],
  );

  const getItemProps = React.useCallback(
    (
      key: string,
      {
        drag = false,
        drop = false,
      }: { drag?: boolean; drop?: "middle" | "whole" | false },
    ) => {
      const cacheKey = `${drag ? "d" : "-"}${drop || "-"}:${key}`;
      let ref = refCache.current.get(cacheKey);
      if (!ref) {
        ref = (element: HTMLElement | null) => {
          cleanups.current.get(cacheKey)?.();
          cleanups.current.delete(cacheKey);
          if (!element) {
            refCache.current.delete(cacheKey);
            return;
          }
          cleanups.current.set(cacheKey, attach(element, key, drag, drop));
        };
        refCache.current.set(cacheKey, ref);
      }
      return {
        ref,
        "data-dragging": draggingId === key ? ("" as const) : undefined,
        "data-drop-over":
          over?.key === key && over.valid ? ("" as const) : undefined,
        "data-drop-invalid":
          over?.key === key && !over.valid ? ("" as const) : undefined,
      };
    },
    [attach, draggingId, over],
  );

  return { getItemProps, draggingId };
}
